"""Transformers-native Qwen3-ASR generate helpers (batch + OOM split)."""

from __future__ import annotations

import logging
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.asr.qwen3_hf_generate")


def _empty_cuda_cache() -> None:
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass


def is_cuda_oom(err: BaseException) -> bool:
    msg = str(err or "").lower()
    if "out of memory" in msg or "cuda oom" in msg or "hip out of memory" in msg:
        return True
    try:
        import torch

        return isinstance(err, torch.cuda.OutOfMemoryError)
    except Exception:
        return False


def _audio_item(item: Any) -> Any:
    """Normalize to path/URL string or float32 ndarray (16 kHz PCM tuples)."""
    if isinstance(item, (str, Path)):
        return str(item)
    if isinstance(item, tuple) and len(item) == 2:
        arr, _sr = item
        try:
            import numpy as np

            return np.asarray(arr, dtype=np.float32)
        except Exception:
            return item
    return item


def _move_inputs_to_model(inputs: Any, bundle: Any) -> Any:
    model = bundle.model
    device = getattr(model, "device", None)
    dtype = getattr(model, "dtype", None) or getattr(bundle, "dtype", None)
    try:
        if hasattr(inputs, "to"):
            if device is not None and dtype is not None:
                return inputs.to(device, dtype)
            if device is not None:
                return inputs.to(device)
    except Exception:
        pass
    return inputs


def _is_continue_final_message_error(err: BaseException) -> bool:
    msg = str(err or "")
    return "continue_final_message" in msg


def _append_language_prefill(processor: Any, inputs: Any, languages: list[str | None]) -> Any:
    """Append ``language <Name><asr_text>`` after the generation prompt (legacy-safe)."""
    import torch

    tokenizer = getattr(processor, "tokenizer", None) or processor
    input_ids = inputs["input_ids"]
    attn = inputs.get("attention_mask")
    rows: list[Any] = []
    masks: list[Any] = []
    max_len = 0
    for i, lang in enumerate(languages):
        row = input_ids[i]
        if hasattr(row, "tolist"):
            ids = list(row.tolist())
        else:
            ids = list(row)
        if lang:
            extra = tokenizer.encode(
                f"language {lang}<asr_text>",
                add_special_tokens=False,
            )
            ids = ids + list(extra)
        rows.append(ids)
        max_len = max(max_len, len(ids))
        if attn is not None:
            m = attn[i]
            m_list = list(m.tolist()) if hasattr(m, "tolist") else list(m)
            masks.append(m_list + [1] * (len(ids) - len(m_list)))
        else:
            masks.append([1] * len(ids))

    pad_id = int(getattr(tokenizer, "pad_token_id", None) or getattr(tokenizer, "eos_token_id", 0) or 0)
    padded_ids = []
    padded_mask = []
    for ids, m in zip(rows, masks):
        pad_n = max_len - len(ids)
        padded_ids.append(ids + [pad_id] * pad_n)
        padded_mask.append(m + [0] * pad_n)
    inputs["input_ids"] = torch.tensor(padded_ids, dtype=getattr(input_ids, "dtype", torch.long))
    inputs["attention_mask"] = torch.tensor(padded_mask, dtype=torch.long)
    return inputs


def _apply_transcription_legacy(processor: Any, audios: list[Any], language: str | None) -> Any:
    """Legacy chat templates only honor ``add_generation_prompt`` (no assistant prefill)."""
    try:
        from transformers.models.qwen3_asr.processing_qwen3_asr import (
            _audio_content_item,
            _prepare_language_inputs,
            make_list_of_audio_chat_template,
        )
    except Exception:
        # Minimal fallback without private helpers.
        audio_items = list(audios)
        languages = [language] * len(audio_items) if language else [None] * len(audio_items)

        def _content(a: Any) -> dict[str, Any]:
            if isinstance(a, str):
                return {"type": "audio", "path": a}
            return {"type": "audio", "audio": a}

        conversations = [
            [{"role": "user", "content": [_content(a)]}] for a in audio_items
        ]
        inputs = processor.apply_chat_template(
            conversations if len(conversations) > 1 else conversations[0],
            tokenize=True,
            return_dict=True,
            add_generation_prompt=True,
        )
        if any(languages):
            inputs = _append_language_prefill(processor, inputs, languages)
        return inputs

    audio_items = list(make_list_of_audio_chat_template(
        audios if len(audios) > 1 else audios[0]
    ))
    languages = _prepare_language_inputs(language, len(audio_items))
    conversations = [
        [{"role": "user", "content": [_audio_content_item(item)]}]
        for item in audio_items
    ]
    inputs = processor.apply_chat_template(
        conversations,
        tokenize=True,
        return_dict=True,
        add_generation_prompt=True,
    )
    if any(lang is not None for lang in languages):
        inputs = _append_language_prefill(processor, inputs, languages)
    return inputs


def apply_transcription_inputs(
    processor: Any,
    audios: list[Any],
    language: str | None,
) -> Any:
    """Build model inputs; fall back when chat template rejects ``continue_final_message``."""
    audio_arg = audios if len(audios) > 1 else audios[0]
    try:
        try:
            return processor.apply_transcription_request(
                audio=audio_arg,
                language=language,
            )
        except TypeError:
            return processor.apply_transcription_request(audios, language=language)
    except ValueError as err:
        if not _is_continue_final_message_error(err):
            raise
        _log.warning(
            "Qwen chat template lacks assistant prefill support; "
            "using add_generation_prompt + language append (%s)",
            str(err).split("Rendered chat:", 1)[0].strip()[:180],
        )
        return _apply_transcription_legacy(processor, audios, language)


def _decode_batch(processor: Any, generated_ids: Any) -> list[Any]:
    """Return list of simple result objects with ``.text`` / ``.transcription``."""
    try:
        parsed = processor.decode(generated_ids, return_format="parsed")
    except TypeError:
        parsed = None
    except Exception:
        parsed = None

    results: list[Any] = []
    if isinstance(parsed, list) and parsed:
        for item in parsed:
            if isinstance(item, dict):
                text = str(item.get("transcription") or item.get("text") or "").strip()
                lang = item.get("language")
                results.append(_SimpleResult(text=text, language=lang))
            else:
                results.append(_SimpleResult(text=str(item or "").strip()))
        return results

    try:
        texts = processor.decode(generated_ids, return_format="transcription_only")
    except TypeError:
        texts = processor.batch_decode(generated_ids, skip_special_tokens=True)
    except Exception:
        texts = processor.batch_decode(generated_ids, skip_special_tokens=True)
    if isinstance(texts, str):
        texts = [texts]
    for t in texts or []:
        results.append(_SimpleResult(text=str(t or "").strip()))
    return results


class _SimpleResult:
    __slots__ = ("text", "transcription", "language", "time_stamps")

    def __init__(
        self,
        *,
        text: str = "",
        language: Any = None,
        time_stamps: Any = None,
    ) -> None:
        self.text = text
        self.transcription = text
        self.language = language
        self.time_stamps = time_stamps


def generate_transcriptions(
    bundle: Any,
    audios: list[Any],
    language: str | None,
    *,
    max_new_tokens: int = 256,
    work_dir: Path | None = None,
    on_oom_cap: Any | None = None,
) -> list[Any]:
    """Batch ASR via ``apply_transcription_request`` + ``generate``.

    ``on_oom_cap(batch_len)`` is invoked when a multi-item batch OOMs before split.
    """
    if not audios:
        return []
    processor = bundle.processor
    model = bundle.model
    try:
        audios_norm = [_audio_item(a) for a in audios]
        inputs = apply_transcription_inputs(processor, audios_norm, language)
        inputs = _move_inputs_to_model(inputs, bundle)
        prompt_len = int(inputs["input_ids"].shape[1])
        gen_kw: dict[str, Any] = {
            "max_new_tokens": int(max_new_tokens),
            "do_sample": False,
        }
        # hhim8826 JA anime LoRA: beam=4 avoids rare greedy repeat loops.
        if getattr(bundle, "prefer_beam_search", False) or getattr(bundle, "is_lora", False):
            gen_kw["num_beams"] = 4
            gen_kw["early_stopping"] = True
        with __import__("torch").inference_mode():
            try:
                output_ids = model.generate(
                    **inputs,
                    **gen_kw,
                )
            except Exception as err:
                if len(audios) > 1 and is_cuda_oom(err):
                    if callable(on_oom_cap):
                        try:
                            on_oom_cap(len(audios))
                        except Exception:
                            pass
                    _log.warning("Qwen -hf batch of %d OOM; splitting: %s", len(audios), err)
                    _empty_cuda_cache()
                    mid = max(1, len(audios) // 2)
                    left = generate_transcriptions(
                        bundle,
                        audios[:mid],
                        language,
                        max_new_tokens=max_new_tokens,
                        work_dir=work_dir,
                        on_oom_cap=on_oom_cap,
                    )
                    right = generate_transcriptions(
                        bundle,
                        audios[mid:],
                        language,
                        max_new_tokens=max_new_tokens,
                        work_dir=work_dir,
                        on_oom_cap=on_oom_cap,
                    )
                    return list(left) + list(right)
                raise

        generated_ids = output_ids[:, prompt_len:]
        return _decode_batch(processor, generated_ids)
    finally:
        pass


def result_text(result: Any) -> str:
    if result is None:
        return ""
    if isinstance(result, dict):
        return str(result.get("transcription") or result.get("text") or "").strip()
    return str(
        getattr(result, "text", None)
        or getattr(result, "transcription", None)
        or ""
    ).strip()
